mapper.select:
WITH bounds AS ( SELECT MIN(price) AS min_price, MAX(price) AS max_price FROM house_record
), bucketed AS ( SELECT CASE WHEN b.max_price = b.min_price THEN 0 WHEN h.price = b.max_price THEN #{bucketCount} - 1 ELSE FLOOR((h.price - b.min_price) / ((b.max_price - b.min_price) / #{bucketCount})) END AS bucket_index, b.min_price, b.max_price FROM house_record h CROSS JOIN bounds b
) SELECT ROUND(min_price + bucket_index * ((max_price - min_price) / #{bucketCount}), 2) AS bucketStart, ROUND(min_price + (bucket_index + 1) * ((max_price - min_price) / #{bucketCount}), 2) AS bucketEnd, COUNT(*) AS count FROM bucketed GROUP BY bucket_index, min_price, max_price ORDER BY bucket_index ASC

SELECT (SELECT ROUND(COALESCE(AVG(square_footage), 0), 2) FROM ( SELECT square_footage, ROW_NUMBER() OVER (ORDER BY square_footage) AS row_num, COUNT(*) OVER () AS total_count FROM house_record
) t WHERE row_num IN (FLOOR((total_count + 1) / 2), FLOOR((total_count + 2) / 2)) ) AS squareFootage,
(SELECT ROUND(COALESCE(AVG(bedrooms), 0), 0) FROM ( SELECT bedrooms, ROW_NUMBER() OVER (ORDER BY bedrooms) AS row_num, COUNT(*) OVER () AS total_count FROM house_record
) t WHERE row_num IN (FLOOR((total_count + 1) / 2), FLOOR((total_count + 2) / 2)) ) AS bedrooms,
(SELECT ROUND(COALESCE(AVG(bathrooms), 0), 1) FROM ( SELECT bathrooms, ROW_NUMBER() OVER (ORDER BY bathrooms) AS row_num, COUNT(*) OVER () AS total_count FROM house_record
) t WHERE row_num IN (FLOOR((total_count + 1) / 2), FLOOR((total_count + 2) / 2)) ) AS bathrooms,
(SELECT ROUND(COALESCE(AVG(year_built), 0), 0) FROM ( SELECT year_built, ROW_NUMBER() OVER (ORDER BY year_built) AS row_num, COUNT(*) OVER () AS total_count FROM house_record
) t WHERE row_num IN (FLOOR((total_count + 1) / 2), FLOOR((total_count + 2) / 2)) ) AS yearBuilt,
(SELECT ROUND(COALESCE(AVG(lot_size), 0), 2) FROM ( SELECT lot_size, ROW_NUMBER() OVER (ORDER BY lot_size) AS row_num, COUNT(*) OVER () AS total_count FROM house_record
) t WHERE row_num IN (FLOOR((total_count + 1) / 2), FLOOR((total_count + 2) / 2)) ) AS lotSize,
(SELECT ROUND(COALESCE(AVG(distance_to_city_center), 0), 2) FROM ( SELECT distance_to_city_center, ROW_NUMBER() OVER (ORDER BY distance_to_city_center) AS row_num, COUNT(*) OVER () AS total_count FROM house_record
) t WHERE row_num IN (FLOOR((total_count + 1) / 2), FLOOR((total_count + 2) / 2)) ) AS distanceToCityCenter,
(SELECT ROUND(COALESCE(AVG(school_rating), 0), 2) FROM ( SELECT school_rating, ROW_NUMBER() OVER (ORDER BY school_rating) AS row_num, COUNT(*) OVER () AS total_count FROM house_record
) t WHERE row_num IN (FLOOR((total_count + 1) / 2), FLOOR((total_count + 2) / 2)) ) AS schoolRating
